function seedShuffle(a,seed){a=[...a];let v=0;for(const c of String(seed))v=(v*31+c.charCodeAt(0))>>>0;for(let i=a.length-1;i>0;i--){v=(1664525*v+1013904223)>>>0;const j=v%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
