const ico=(name)=>{const p={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',course:'<path d="M3 5h8a4 4 0 0 1 4 4v12a4 4 0 0 0-4-4H3z"/><path d="M21 5h-2a4 4 0 0 0-4 4v12a4 4 0 0 1 4-4h2z"/>',forms:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M8 10h8M8 14h8M8 18h5"/>',practice:'<path d="M8 3h8M10 3v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M8 15h8"/>',library:'<path d="M3 4h5v16H3zM10 4h5v16h-5zM17 5l4-1 3 15-4 1z"/>',certificate:'<circle cx="12" cy="9" r="6"/><path d="m8 14-2 7 6-3 6 3-2-7"/>',facilitator:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-4a7 7 0 0 1 14 0v4M3 21h18"/>',clinical:'<path d="M12 3v18M3 12h18"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',play:'<path d="m7 4 14 8-14 8z"/>',check:'<path d="m5 12 5 5L20 7"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4 9 9 0 1 0 20 15z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};return '<svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(p[name]||p.arrow)+'</svg>'};
